package com.xdownload.mobile;import java.io.*;import java.security.*;import java.util.function.BooleanSupplier;
final class ActualDuplicates{static String hash(InputStream in,long size,BooleanSupplier go)throws Exception{if(in==null||size<0)throw new IOException("Unknown file");MessageDigest md=MessageDigest.getInstance("SHA-256");byte[] b=new byte[65536];long n=0;int x;while(go.getAsBoolean()&&(x=in.read(b))!=-1){if(x>size-n)throw new IOException("Changed length");md.update(b,0,x);n+=x;}if(!go.getAsBoolean()||n!=size)throw new IOException("Incomplete scan");StringBuilder s=new StringBuilder(64);for(byte v:md.digest())s.append(String.format(java.util.Locale.ROOT,"%02x",v&255));return s.toString();}}